-- IAM RBAC: permission catalogue, roles, grants, scopes, ceilings, separation-of-duties rules.
-- The INSERT blocks are GENERATED by tools/gen-migrations.js from tools/catalogue.js. Do not edit by hand.

CREATE TABLE permission (
    permission_code  VARCHAR(60)  PRIMARY KEY,
    module           VARCHAR(20)  NOT NULL,
    description      VARCHAR(200) NOT NULL,
    risk_level       VARCHAR(10)  NOT NULL CHECK (risk_level IN ('LOW', 'MEDIUM', 'HIGH', 'CRITICAL')),
    requires_mfa     BOOLEAN      NOT NULL DEFAULT FALSE,
    applies_to       VARCHAR(3)   NOT NULL CHECK (applies_to ~ '^[SCV]+$')
);

CREATE TABLE role (
    role_code     VARCHAR(40)  PRIMARY KEY,
    role_name     VARCHAR(80)  NOT NULL,
    role_kind     VARCHAR(10)  NOT NULL CHECK (role_kind IN ('STAFF', 'CUSTOMER', 'SERVICE')),
    description   VARCHAR(300) NOT NULL DEFAULT '',
    mfa_required  BOOLEAN      NOT NULL DEFAULT FALSE,
    system_role   BOOLEAN      NOT NULL DEFAULT FALSE,
    status        VARCHAR(10)  NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'RETIRED')),
    created_at    TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at    TIMESTAMPTZ  NOT NULL DEFAULT now()
);

CREATE TABLE role_permission (
    role_code        VARCHAR(40) NOT NULL REFERENCES role (role_code),
    permission_code  VARCHAR(60) NOT NULL REFERENCES permission (permission_code),
    PRIMARY KEY (role_code, permission_code)
);
CREATE INDEX ix_role_permission_perm ON role_permission (permission_code);

-- A ceiling on the amount a role may use with one permission, per currency ('*' = any currency).
CREATE TABLE permission_limit (
    role_code        VARCHAR(40)   NOT NULL,
    permission_code  VARCHAR(60)   NOT NULL,
    currency         VARCHAR(3)    NOT NULL,
    max_amount       NUMERIC(20,2) NOT NULL CHECK (max_amount >= 0),
    PRIMARY KEY (role_code, permission_code, currency),
    FOREIGN KEY (role_code, permission_code) REFERENCES role_permission (role_code, permission_code) ON DELETE CASCADE,
    CHECK (currency = '*' OR currency ~ '^[A-Z]{3}$')
);

CREATE TABLE user_role (
    assignment_id  BIGSERIAL PRIMARY KEY,
    user_id        BIGINT      NOT NULL REFERENCES app_user (user_id),
    role_code      VARCHAR(40) NOT NULL REFERENCES role (role_code),
    valid_from     DATE        NOT NULL DEFAULT CURRENT_DATE,
    valid_to       DATE,
    granted_by     VARCHAR(60) NOT NULL,
    granted_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    ended_at       TIMESTAMPTZ,
    CHECK (valid_to IS NULL OR valid_to >= valid_from)
);
CREATE INDEX ix_user_role_user ON user_role (user_id) WHERE ended_at IS NULL;
CREATE INDEX ix_user_role_role ON user_role (role_code) WHERE ended_at IS NULL;

CREATE TABLE user_scope (
    user_id      BIGINT      NOT NULL REFERENCES app_user (user_id),
    scope_type   VARCHAR(10) NOT NULL CHECK (scope_type IN ('BRANCH', 'PRODUCT', 'CURRENCY')),
    scope_value  VARCHAR(40) NOT NULL,
    PRIMARY KEY (user_id, scope_type, scope_value)
);

CREATE TABLE sod_rule (
    rule_id       BIGSERIAL PRIMARY KEY,
    permission_a  VARCHAR(60)  NOT NULL REFERENCES permission (permission_code),
    permission_b  VARCHAR(60)  NOT NULL REFERENCES permission (permission_code),
    description   VARCHAR(200) NOT NULL,
    created_at    TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CHECK (permission_a < permission_b),
    UNIQUE (permission_a, permission_b)
);

CREATE TABLE oauth_client_role (
    client_id  VARCHAR(80) NOT NULL REFERENCES oauth_client (client_id),
    role_code  VARCHAR(40) NOT NULL REFERENCES role (role_code),
    PRIMARY KEY (client_id, role_code)
);

