INSERT INTO role (role_code, role_name, role_kind, description, mfa_required, system_role) VALUES
  ('IAM_USER_ADMIN', 'Identity administrator: users', 'STAFF', 'Creates and maintains users and customer links; suspends, unlocks, offboards and resets. Cannot grant access.', TRUE, TRUE),
  ('IAM_ACCESS_ADMIN', 'Identity administrator: access', 'STAFF', 'Assigns roles and scopes to users. Cannot create users or define roles.', TRUE, TRUE),
  ('IAM_SECURITY_ADMIN', 'Identity administrator: security', 'STAFF', 'Defines roles and separation-of-duties rules, manages service accounts, signing keys, webhooks and approval types.', TRUE, TRUE),
  ('SECURITY_APPROVER', 'Identity approver', 'STAFF', 'Second person for customer links, approvals of identity actions and clear-data requests.', TRUE, TRUE),
  ('AUDITOR', 'Auditor (read only)', 'STAFF', 'Reads everything and the audit trail; changes nothing.', FALSE, TRUE),
  ('LOAN_OFFICER', 'Loan officer', 'STAFF', 'Creates loan accounts and records mortgage details (maker).', FALSE, TRUE),
  ('LOAN_APPROVER', 'Loan approver', 'STAFF', 'Disburses loans (checker for creation).', TRUE, TRUE),
  ('PAYMENTS_OFFICER', 'Payments officer', 'STAFF', 'Posts EMI, part-payment and foreclosure.', TRUE, TRUE),
  ('PRODUCT_MANAGER', 'Product manager', 'STAFF', 'Maintains loan products and benchmark rates (maker).', FALSE, TRUE),
  ('PRODUCT_APPROVER', 'Product approver', 'STAFF', 'Approves loan product changes (checker).', TRUE, TRUE),
  ('ACCOUNTING_MAKER', 'Accounting configurator', 'STAFF', 'Edits entry templates, routes and event modes (maker).', FALSE, TRUE),
  ('ACCOUNTING_CHECKER', 'Accounting approver', 'STAFF', 'Approves templates and routes (checker).', TRUE, TRUE),
  ('ACCOUNTING_OPS', 'Accounting operations', 'STAFF', 'Runs reconciliation, snapshot and the opening-balance cutover; works posting exceptions.', TRUE, TRUE),
  ('BATCH_OPERATOR', 'Batch operator', 'STAFF', 'Watches and triggers batch jobs and end of day.', TRUE, TRUE),
  ('BATCH_ADMIN', 'Batch administrator', 'STAFF', 'Changes batch job configuration.', TRUE, TRUE),
  ('PLATFORM_ADMIN', 'Platform administrator', 'STAFF', 'Reference data, ledger outbox and (sandbox only) maintenance.', TRUE, TRUE),
  ('BRANCH_MANAGER', 'Branch manager', 'STAFF', 'Branch-scoped read of loans plus limits and collateral; approves loan creation as a checker.', FALSE, TRUE),
  ('LCM_MAKER', 'Limits and collateral officer', 'STAFF', 'Creates facilities, proposes changes, registers collateral and valuations (maker).', FALSE, TRUE),
  ('LCM_CHECKER', 'Limits and collateral approver', 'STAFF', 'Approves facility changes, excess and valuations; activates and releases collateral (checker).', TRUE, TRUE),
  ('LCM_ADMIN', 'Limits and collateral administrator', 'STAFF', 'Runs the monitoring sweep and the lending bridge.', TRUE, TRUE),
  ('CUSTOMER_SELF', 'Customer (self service)', 'CUSTOMER', 'A retail customer using the portal on own accounts.', FALSE, TRUE),
  ('SVC_LENDING', 'Service: lending-service', 'SERVICE', 'Lending reserves, confirms, releases and repays limits and asks for approvals.', FALSE, TRUE),
  ('SVC_BATCH', 'Service: lending-batch-service', 'SERVICE', 'Batch jobs call lending and accounting endpoints.', FALSE, TRUE),
  ('SVC_ADMIN', 'Service: lending-admin-service', 'SERVICE', 'The admin console back end submits approvals and checks access for the signed-in user.', FALSE, TRUE),
  ('SVC_PORTAL', 'Service: customer portal back end', 'SERVICE', 'The portal back end reads on behalf of a customer.', FALSE, TRUE),
  ('SVC_LCM', 'Service: lending-lcm-service', 'SERVICE', 'LCM submits facility, valuation and excess approvals and consumes them.', FALSE, TRUE);
