INSERT INTO sod_rule (permission_a, permission_b, description) VALUES
  ('acct.template.approve', 'acct.template.edit', 'The person who writes an entry template cannot approve it'),
  ('acct.route.approve', 'acct.route.edit', 'The person who writes a route cannot approve it'),
  ('lcm.facility.approve', 'lcm.facility.change', 'The person who proposes a facility change cannot approve it'),
  ('lcm.facility.approve', 'lcm.facility.create', 'The person who creates a facility cannot approve it'),
  ('lcm.excess.approve', 'lcm.excess.create', 'The person who proposes a temporary excess cannot approve it'),
  ('lcm.valuation.approve', 'lcm.valuation.create', 'The person who proposes a valuation cannot approve it'),
  ('loan.account.create', 'loan.account.disburse', 'The person who creates a loan cannot disburse it'),
  ('loan.product.approve', 'loan.product.manage', 'The person who changes a product cannot approve the change'),
  ('iam.assignment.manage', 'iam.user.create', 'The person who creates users cannot also grant them access'),
  ('iam.assignment.manage', 'iam.role.manage', 'The person who defines roles cannot also grant them to users'),
  ('iam.assignment.manage', 'iam.audit.read', 'Whoever grants access cannot be the one who audits the grants'),
  ('iam.audit.read', 'iam.role.manage', 'Whoever defines roles cannot be the one who audits them'),
  ('iam.audit.read', 'iam.client.manage', 'Whoever manages service accounts cannot be the one who audits them'),
  ('ops.maintenance.approve', 'ops.maintenance.clear', 'The person who asks to clear data cannot approve the request');
